import{_ as t,a0 as l,w as o,s as c,ao as d,I as i,x as n,a1 as p,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"4 步打包一個新的 Python 模組 | LCTT x X-CMD","titleTemplate":false,"description":"4 步打包一個新的 Python 模組 | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"4 步打包一個新的 Python 模組 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"4 步打包一個新的 Python 模組 | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220630 Package a new Python module in 4 steps","title":"4 步打包一個新的 Python 模組","tag":"202209","desc":""},"relativePath":"202209/20220630 Package a new Python module in 4 steps.md","filePath":"[post].md"}'),r={name:"202209/20220630 Package a new Python module in 4 steps.md"};function h(g,s,u,k,b,y){const a=l("Link");return o(),c("div",null,[s[15]||(s[15]=d(`<h1 id="_4-步打包一個新的-python-模組" tabindex="-1">4 步打包一個新的 Python 模組 <a class="header-anchor" href="#_4-步打包一個新的-python-模組" aria-label="Permalink to “4 步打包一個新的 Python 模組”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202209/14/155051kzjuzhzvmllmv2b5.jpg" alt=""></p><blockquote><p>pyp2rpm 使得創建 RPM 包的過程更加自動化。</p></blockquote><p>當你安裝一個應用程序時，你通常是在安裝一個軟件包，其中包含應用程序的可執行代碼和重要文件，如文檔、圖標等。在 Linux上，軟件一般被打包成 RPM 或 DEB 等格式，用户只要通過 <code>dnf</code> 或者 <code>apt</code> 等命令就可以進行安裝了，這取決於你使用的 Linux 發行版。然而幾乎每天都有新的 Python 模組發佈，因此你很容易遇到一個尚未打包的 Python 模組。這就是 <code>pyp2rpm</code> 存在的意義了。</p><p>最近我在嘗試安裝一個叫 <code>python-concentration</code> 的模組，但是進展並不太順利：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install python-concentration</span></span>
<span class="line"><span>Updating Subscription Management repositories.</span></span>
<span class="line"><span>Last metadata expiration check: 1:23:32 ago on Sat 11 Jun 2022 06:37:25.</span></span>
<span class="line"><span>No match for argument: python-concentration</span></span>
<span class="line"><span>Error: Unable to find a match: python-concentration</span></span></code></pre></div><p>雖然這是一個發佈在 PyPi 的包，但它仍不能被打包成 RPM 包。好消息是你可以使用 <code>pyp2rpm</code> 以一個相對簡單的過程將它打包成 RPM 包。</p><p>首先你需要設置兩個目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir rpmbuild</span></span>
<span class="line"><span>$ cd rpmbuild &amp;&amp; mkdir SPECS</span></span></code></pre></div><p>像這樣去安裝 <code>pyp2rpm</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install pyp2rpm</span></span></code></pre></div><h3 id="_1、生成-spec-文件" tabindex="-1">1、生成 spec 文件 <a class="header-anchor" href="#_1、生成-spec-文件" aria-label="Permalink to “1、生成 spec 文件”">​</a></h3><p>RPM 包的基礎是一種 spec 文件，這個文件包含你創建這個包的所有信息，如所需的依賴關係、應用的版本號、安裝的文件等信息。當指向某個 Python 模組時，<code>pyp2rpm</code> 會為它構建一個 spec 文件，你可以用它來創建 RPM 包。</p><p>下面以 <code>python-concentration</code> 為例演示如何構建一個 spec 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pyp2rpm concentration &gt; ~/rpmbuild/SPECS/concentration.spec</span></span></code></pre></div><p>下面是它生成的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Created by pyp2rpm-3.3.8</span></span>
<span class="line"><span>%global pypi_name concentration</span></span>
<span class="line"><span>%global pypi_version 1.1.5</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Name:           python-%{pypi_name}</span></span>
<span class="line"><span>Version:        %{pypi_version}</span></span>
<span class="line"><span>Release:        1%{?dist}</span></span>
<span class="line"><span>Summary:        Get work done when you need to, goof off when you don&#39;t</span></span>
<span class="line"><span></span></span>
<span class="line"><span>License:        None</span></span>
<span class="line"><span>URL:            None</span></span>
<span class="line"><span>Source0:        %{pypi_source}</span></span>
<span class="line"><span>BuildArch:      noarch</span></span>
<span class="line"><span></span></span>
<span class="line"><span>BuildRequires:  python3-devel</span></span>
<span class="line"><span>BuildRequires:  python3dist(setuptools)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>%description</span></span>
<span class="line"><span>Concentration [![PyPI version]( [![Test Status]( [![Lint Status]( [![codecov](</span></span>
<span class="line"><span></span></span>
<span class="line"><span>%package -n     python3-%{pypi_name}</span></span>
<span class="line"><span>Summary:        %{summary}</span></span>
<span class="line"><span>%{?python_provide:%python_provide python3-%{pypi_name}}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Requires:       (python3dist(hug) &gt;= 2.6.1 with python3dist(hug) &lt; 3~~)</span></span>
<span class="line"><span>Requires:       python3dist(setuptools)</span></span>
<span class="line"><span>%description -n python3-%{pypi_name}</span></span>
<span class="line"><span>Concentration [![PyPI version]( [![Test Status]( [![Lint Status]( [![codecov](</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>%prep</span></span>
<span class="line"><span>%autosetup -n %{pypi_name}-%{pypi_version}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>%build</span></span>
<span class="line"><span>%py3_build</span></span>
<span class="line"><span></span></span>
<span class="line"><span>%install</span></span>
<span class="line"><span>%py3_install</span></span>
<span class="line"><span></span></span>
<span class="line"><span>%files -n python3-%{pypi_name}</span></span>
<span class="line"><span>%license LICENSE</span></span>
<span class="line"><span>%doc README.md</span></span>
<span class="line"><span>%{_bindir}/concentration</span></span>
<span class="line"><span>%{python3_sitelib}/%{pypi_name}</span></span>
<span class="line"><span>%{python3_sitelib}/%{pypi_name}-%{pypi_version}-py%{python3_version}.egg-info</span></span>
<span class="line"><span></span></span>
<span class="line"><span>%changelog</span></span>
<span class="line"><span>*  - 1.1.5-1</span></span>
<span class="line"><span>- Initial package.</span></span></code></pre></div><h3 id="_2、運行-rpmlint" tabindex="-1">2、運行 rpmlint <a class="header-anchor" href="#_2、運行-rpmlint" aria-label="Permalink to “2、運行 rpmlint”">​</a></h3><p>為了確保 spec 文件符合標準，你需要對文件使用 <code>rpmlint</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rpmlint ~/rpmbuild/SPEC/concentration.spec</span></span>
<span class="line"><span>error: bad date in %changelog: - 1.1.5-1</span></span>
<span class="line"><span>0 packages and 1 specfiles checked; 0 errors, 0 warnings.</span></span></code></pre></div><p>看起來更新日誌（<code>%changelog</code>）需要記錄日期。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>%changelog</span></span>
<span class="line"><span>* Sat Jun 11 2022 Tux &lt;tux@example.com&gt; - 1.1.5-1</span></span></code></pre></div><p>再次運行 <code>rpmint</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rpmlint ~/rpmbuild/SPEC/concentration.spec</span></span>
<span class="line"><span>0 packages and 1 specfiles checked; 0 errors, 0 warnings.</span></span></code></pre></div><p>成功！</p><h3 id="_3、下載源碼" tabindex="-1">3、下載源碼 <a class="header-anchor" href="#_3、下載源碼" aria-label="Permalink to “3、下載源碼”">​</a></h3><p>你需要下載好打包的代碼才能進一步構建 RPM 包。一種簡單的方式是解析你的 spec 文件以獲取源碼的網址。</p><p>首先，通過 <code>dnf</code> 安裝 <code>spectool</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install spectool</span></span></code></pre></div><p>然後通過 <code>spectool</code> 來下載源碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd ~/rpmbuild</span></span>
<span class="line"><span>$ spectool -g -R SPEC/concentration.spec</span></span>
<span class="line"><span>Downloading: https://files.pythonhosted.org/...concentration-1.1.5.tar.gz</span></span>
<span class="line"><span>   6.0 KiB / 6.0 KiB    [=====================================]</span></span>
<span class="line"><span>Downloaded: concentration-1.1.5.tar.gz</span></span></code></pre></div><p>這樣就創建了一個 <code>SOURCES</code> 目錄並將源碼放入其中。</p><h3 id="_4、構建源軟件包" tabindex="-1">4、構建源軟件包 <a class="header-anchor" href="#_4、構建源軟件包" aria-label="Permalink to “4、構建源軟件包”">​</a></h3><p>現在你已經驗證過 spec 文件了，接下來就可以通過 <code>rpmbuild</code> 構建源軟件包了。如果你還沒有安裝 <code>rpmbuild</code>，你也可以通過 <code>dnf</code> 安裝 <code>rpm-build</code> 包（或者在使用 <code>rpmbuild</code> 命令時根據終端的的提示進行安裝）。</p><p>參數 <code>-bs</code> 表示構建源軟件包。添加這個參數會產生一個 src.rpm 文件，這是一個用於為特定架構重新構建的通用包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rpmbuild -bs SPECS/concentration.spec</span></span>
<span class="line"><span>Wrote: ~/rpmbuild/SRPMS/python-concentration-1.1.5-1.el9.src.rpm</span></span></code></pre></div><p>為你的系統構建一個可安裝的 RPM 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rpmbuild –rebuild SRPMS/python-concentration-1.1.5-1.el9.src.rpm</span></span>
<span class="line"><span>error: Failed build dependencies:</span></span>
<span class="line"><span>        python3-devel is needed by python-concentration-1.1.5-1.el9.noarch</span></span></code></pre></div><p>看起來這個包需要安裝 Python 的開發庫才能繼續構建。安裝它們以繼續構建。這一次，構建成功了，並且渲染了更多的輸出（為了清楚起見，我在這裏簡略了輸出）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install python3-devel -y</span></span>
<span class="line"><span>$ rpmbuild –rebuild SRPMS/python-concentration-1.1.5-1.el9.src.rpm</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>Executing(--clean): /bin/sh -e /var/tmp/rpm-tmp.TYA7l2</span></span>
<span class="line"><span>+ umask 022</span></span>
<span class="line"><span>+ cd /home/bogus/rpmbuild/BUILD</span></span>
<span class="line"><span>+ rm -rf concentration-1.1.5</span></span>
<span class="line"><span>+ RPM_EC=0</span></span>
<span class="line"><span>++ jobs -p</span></span>
<span class="line"><span>+ exit 0</span></span></code></pre></div><p>你的 RPM 包現在已經構建在 <code>RPMS</code> 子目錄下，像平常一樣使用 <code>dnf</code> 安裝它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install RPMS/noarch/python3-concentration*rpm</span></span></code></pre></div><h3 id="為什麼不使用-pypi" tabindex="-1">為什麼不使用 PyPi？ <a class="header-anchor" href="#為什麼不使用-pypi" aria-label="Permalink to “為什麼不使用 PyPi？”">​</a></h3><p>通常情況下我們並不需要將 Python 模組打包成 RPM 包。通過 PyPi 來安裝模組也是可以接受的，但是 PyPi 會安裝額外的包管理器對你的模組進行檢查和更新。當你使用 <code>dnf</code> 來安裝 RPM 包時，你在安裝完成時就能夠獲取到完整的安裝列表。有了 <code>pyp2rpm</code> 之後，這個過程就變得快速、簡單且自動化了。</p><hr>`,45)),i("p",null,[s[1]||(s[1]=n("via: ",-1)),p(a,{href:"https://opensource.com/article/22/6/package-python-module-rpm"},{default:e(()=>[...s[0]||(s[0]=[n("https://opensource.com/article/22/6/package-python-module-rpm",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=n("作者：",-1)),p(a,{href:"https://opensource.com/users/sumantro"},{default:e(()=>[...s[2]||(s[2]=[n("Sumantro Mukherjee",-1)])]),_:1}),s[7]||(s[7]=n(" 選題：",-1)),p(a,{href:"https://github.com/lkxed"},{default:e(()=>[...s[3]||(s[3]=[n("lkxed",-1)])]),_:1}),s[8]||(s[8]=n(" 譯者：",-1)),p(a,{href:"https://github.com/Return7g"},{default:e(()=>[...s[4]||(s[4]=[n("Return7g",-1)])]),_:1}),s[9]||(s[9]=n(" 校對：",-1)),p(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[5]||(s[5]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=n("本文由 ",-1)),p(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[10]||(s[10]=[n("LCTT",-1)])]),_:1}),s[13]||(s[13]=n(" 原創編譯，",-1)),p(a,{href:"https://linux.cn/"},{default:e(()=>[...s[11]||(s[11]=[n("Linux中國",-1)])]),_:1}),s[14]||(s[14]=n(" 榮譽推出",-1))])])}const C=t(r,[["render",h]]);export{P as __pageData,C as default};
